color_bg = "#121926"     # Dark Navy background
color_heads = "#3b82f6"  # Blue line
color_tails = "#059669"  # Green line
color_pink = "#f472b6"   # Pink for Probability highlighting
color_grid = "#2d3748"

plt.rcParams.update({
    "figure.facecolor": color_bg, 
    "axes.facecolor": color_bg,
    "axes.edgecolor": "#444b5a", 
    "axes.labelcolor": "#ffffff",
    "xtick.color": "#aeb4c1", 
    "ytick.color": "#aeb4c1",
    "grid.color": color_grid, 
    "text.color": "#ffffff"
})

def apply_table_style(tbl):
    """Applies the dark theme and pink highlights to the probability tables."""
    for (r, c), cell in tbl.get_celld().items():
        cell.set_edgecolor("#444b5a")
        cell.set_facecolor(color_bg)
        if r == 0: 
            cell.set_facecolor("#1f2937") # Header row
        if c == 2 and r > 0: 
            cell.get_text().set_color(color_pink) # Pink Probability column
        if r == 1 and c < 2: 
            cell.get_text().set_color(color_heads) # Blue Heads text
        if r == 2 and c < 2: 
            cell.get_text().set_color(color_tails) # Green Tails text

all_h_global, all_t_global = [], []
coins = list(raw_data.keys())

# --- 2. POP-UPS 1-8: INDIVIDUAL COINS ---
for coin in coins:
    data = raw_data[coin]
    h_list = [item for sublist in data["heads_groups"] for item in sublist]
    t_list = [item for sublist in data["tails_groups"] for item in sublist]
    all_h_global.extend(h_list)
    all_t_global.extend(t_list)
    
    h_path, t_path = np.cumsum(h_list), np.cumsum(t_list)
    f_h, f_t, total = h_path[-1], t_path[-1], len(h_list)

    fig, ax = plt.subplots(figsize=(9, 7))
    ax.plot(h_path, color=color_heads, linewidth=2.5, label='Heads (H)')
    ax.plot(t_path, color=color_tails, linewidth=2.5, label='Tails (T)')
    ax.set_title(f"Coin Class: {coin}", fontweight='bold', fontsize=14, pad=15)
    ax.set_xlabel("Toss #")
    ax.set_ylabel("Cumulative Count")
    ax.grid(True, alpha=0.2)
    
    t_data = [
        ["Outcome", "Count", "Probability"], 
        ["Heads (H)", f"{f_h}", f"{(f_h/total)*100:.1f}%"], 
        ["Tails (T)", f"{f_t}", f"{(f_t/total)*100:.1f}%"]
    ]
    tbl = ax.table(cellText=t_data, loc='bottom', bbox=[0.15, -0.45, 0.7, 0.3], cellLoc='center')
    apply_table_style(tbl)
    
    plt.subplots_adjust(bottom=0.35)
    plt.show()

# --- 3. 9th POP-UP: THE 8-GRAPH GRID (FIXED SPACING) ---
# Spacing adjusted so titles like '2Peso' or '20A' are not hit by the graph
fig_grid = plt.figure(figsize=(20, 12)) 
gs = gridspec.GridSpec(2, 4, hspace=0.6, wspace=0.3) 

for i, coin in enumerate(coins):
    ax = fig_grid.add_subplot(gs[i//4, i%4])
    data = raw_data[coin]
    h_p = np.cumsum([item for sublist in data["heads_groups"] for item in sublist])
    t_p = np.cumsum([item for sublist in data["tails_groups"] for item in sublist])
    
    ax.plot(h_p, color=color_heads, linewidth=2) 
    ax.plot(t_p, color=color_tails, linewidth=2)
    
    # Pad=20 ensures title is safe from line graphs
    ax.set_title(coin, fontsize=14, fontweight='bold', pad=20) 
    ax.grid(True, alpha=0.1)

fig_grid.suptitle("All Coin Classes (Grid View)", fontsize=22, fontweight='bold', y=0.98)
plt.tight_layout(rect=[0, 0.05, 1, 0.93]) 
plt.show()

# --- 4. 10th POP-UP: THE COMBINED TOTAL (STEP 6) ---
h_cum_g, t_cum_g = np.cumsum(all_h_global), np.cumsum(all_t_global)
final_h_g, final_t_g = h_cum_g[-1], t_cum_g[-1]
grand_total = final_h_g + final_t_g

fig_final, ax_g = plt.subplots(figsize=(14, 9))
ax_g.plot(h_cum_g, color=color_heads, linewidth=3)
ax_g.plot(t_cum_g, color=color_tails, linewidth=3)
ax_g.set_title('Canvas H & T (Combined Overall)', fontsize=20, fontweight='bold', pad=20)
ax_g.set_xlabel("Total Toss # (Concatenated)")
ax_g.set_ylabel("Cumulative Count")
ax_g.grid(True, alpha=0.2)

g_data = [
    ["Outcome", "Count", "Probability"], 
    ["Heads (H)", f"{final_h_g}", f"{(final_h_g/grand_total)*100:.1f}%"], 
    ["Tails (T)", f"{final_t_g}", f"{(final_t_g/grand_total)*100:.1f}%"], 
    ["Total", f"{grand_total}", "100.0%"]
]
g_tbl = ax_g.table(cellText=g_data, loc='bottom', bbox=[0.15, -0.45, 0.7, 0.3], cellLoc='center')
apply_table_style(g_tbl)

plt.subplots_adjust(bottom=0.35) 
plt.show()